   "orig": "尽管看着荒谬，这其实正是对「以这种方式提出、且没有外界干涉」的问题的正确答案。实践中我们绝不会发现气体全在 R 里。这个论证只是告诉我们：如果我们真的发现气体自发地全在 R 里，它必定曾如何行为——而我们不会发现这种事。这里没有悖论。但它回避了我希望读者考虑的问题：像「气体全在 R 里」这样的情形，实践中究竟是怎么出现的？在我们实际的宇宙里，这不成问题（取 V_R 的放松定义，允许千分之一的气体在 R 之外）。可以设想某位实验者先往整个容器泵入十倍所需的气体，再关上阀门，最后用真空泵抽容器主体，把那 90% 几乎全抽走。整个过程里，熵始终在上升，符合第二定律。当然，要在相空间里讨论这件事，我们需要一个更大的相空间，把实验者也纳入——大概还要把宇宙的相当一部分纳进来，或许一直延伸到太阳甚至更远。实验者身体的熵靠进食和呼吸维持在很低的水平。为简单起见，假定泵是手动操作的——否则还得操心燃料来源的低熵从何而来（那会引出与眼下目的无关的问题）。实验者低熵的一部分被转移到容器及其气体上，用来把气体弄进 R。实验者食物里和空气里的低熵，归根到底来自外面的太阳。太阳这个具体角色，我很快会回来谈。",
